                {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((day, idx) => (
                  <span key={idx}>{day}</span>
                ))}
              </div>

              <div className="flex-1 grid grid-flow-col gap-2.5" style={{ gridTemplateRows: 'repeat(7, 1fr)', gridAutoColumns: '20px' }}>
                {heatmapData.map((day, idx) => (
                  <div
                    key={idx}
                    className={`${getHeatColor(day.count)} rounded-md hover:scale-125 cursor-pointer transition-all duration-200 group relative`}
                    style={{ 
                      gridRow: day.day + 1,
                      width: '20px',
                      height: '20px'
                    }}
                  >
                    <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-3 px-3 py-2 bg-slate-900 text-white text-sm font-bold rounded-lg opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none z-10 shadow-2xl border-2 border-slate-700">
                      {new Date(day.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                      <div className="text-indigo-400">{day.count} session{day.count !== 1 ? 's' : ''}</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="flex items-center gap-4 mt-8 ml-16">
              <span className="text-sm text-slate-400 font-bold">Less</span>
              <div className="w-5 h-5 bg-slate-800/50 border border-slate-700/30 rounded-md"></div>
              <div className="w-5 h-5 bg-indigo-900/60 border border-indigo-800 rounded-md"></div>
              <div className="w-5 h-5 bg-indigo-600/70 border border-indigo-500 rounded-md"></div>
              <div className="w-5 h-5 bg-indigo-500 border border-indigo-400 rounded-md shadow-lg shadow-indigo-500/30"></div>
              <span className="text-sm text-slate-400 font-bold">More</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="flex min-h-screen bg-slate-950">

      {/* Achievement Toast */}
      {showAchievement && (
        <div className="fixed top-6 right-6 z-50 bg-gradient-to-br from-slate-800 to-slate-900 border-2 border-emerald-500 rounded-2xl shadow-2xl px-6 py-5 max-w-sm animate-bounce">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 bg-emerald-500/20 rounded-xl flex items-center justify-center">
              <svg className="w-7 h-7 text-emerald-400" fill="currentColor" viewBox="0 0 20 20">
                <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
              </svg>
            </div>
            <div>
              <div className="font-bold text-white text-base">Achievement Unlocked! 🎉</div>
              <div className="text-sm text-emerald-400 mt-1">Completed 5 Sessions</div>
            </div>
          </div>
        </div>
      )}

      {/* Sidebar */}
      <aside className="w-72 bg-slate-900 border-r-2 border-slate-800 flex flex-col">
        <div className="p-6 border-b-2 border-slate-800">
          <h1 className="text-2xl font-bold text-white mb-1">Saarthi ✨</h1>
          <p className="text-xs text-slate-400 font-semibold">AI Learning Platform</p>
        </div>

        <div className="flex-1 p-4">
          <nav className="space-y-2">
            {[
              { view: 'dashboard', icon: 'M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6', label: 'Dashboard', emoji: '📊' },
              { view: 'tutors', icon: 'M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z', label: 'AI Tutors', badge: true, emoji: '🎓' },
              { view: 'history', icon: 'M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z', label: 'History', count: sessions.length, emoji: '📚' },
              { view: 'notes', icon: 'M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z', label: 'Notes', count: JSON.parse(localStorage.getItem('quickNotes') || '[]').length, emoji: '📝' }
            ].map(({ view, icon, label, badge, count, emoji }) => (
              <button 
                key={view}
                onClick={() => setActiveView(view)}
                className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-xl text-sm font-bold transition-all duration-300 ${
                  activeView === view
                    ? 'bg-gradient-to-r from-indigo-600 to-indigo-500 text-white shadow-lg shadow-indigo-500/30'
                    : 'text-slate-400 hover:text-white hover:bg-slate-800'
                }`}
              >
                <span className="text-lg">{emoji}</span>
                {label}
                {badge && <span className="ml-auto w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse"></span>}
                {count !== undefined && count > 0 && (
                  <span className="ml-auto px-2.5 py-1 bg-slate-800 text-slate-300 text-xs font-bold rounded-lg">
                    {count}
                  </span>
                )}
              </button>
            ))}
          </nav>

          <div className="mt-6 p-5 bg-slate-800/50 border-2 border-slate-800 rounded-xl">
            <div className="text-xs text-slate-500 mb-4 font-bold uppercase tracking-wider">This Week</div>
            <div className="space-y-4">
              {[
                { label: 'Sessions', value: sessions.filter(s => {
                  const sessionDate = new Date(s.created_at);
                  const weekAgo = new Date();
                  weekAgo.setDate(weekAgo.getDate() - 7);
                  return sessionDate >= weekAgo;
                }).length, emoji: '🎯' },
                { label: 'Hours', value: `${totalHours}h`, emoji: '⏱️' },
                { label: 'Streak', value: `${streak}d`, emoji: '🔥' }
              ].map(({ label, value, emoji }) => (
                <div key={label} className="flex items-center justify-between text-sm">
                  <span className="text-slate-400 flex items-center gap-2">
                    <span>{emoji}</span>
                    {label}
                  </span>
                  <span className="text-white font-bold text-base">{value}</span>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="p-4 border-t-2 border-slate-800">
          <div className="flex items-center gap-3 px-4 py-3 bg-slate-800/50 rounded-xl mb-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white font-bold text-base shadow-lg">
              {user?.name?.charAt(0)?.toUpperCase() || 'S'}
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-sm font-bold text-white truncate">{user?.name || 'Student'}</div>
              <div className="text-xs text-slate-400 truncate">{user?.email}</div>
            </div>
          </div>
          <button 
            onClick={handleLogout}
            className="w-full px-4 py-3 bg-slate-800 hover:bg-red-500/20 border-2 border-slate-700 hover:border-red-500/50 text-slate-300 hover:text-red-400 rounded-xl text-sm font-bold transition-all duration-300 flex items-center justify-center gap-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
            </svg>
            Logout
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto bg-slate-950" key={notesKey}>
        {activeView === 'dashboard' && renderDashboardView()}
        {activeView === 'tutors' && renderTutorsView()}
        {activeView === 'history' && renderHistoryView()}
        {activeView === 'notes' && renderNotesView()}
      </main>
    </div>
  );
}
